import numpy as np

def compute_order_amount(on_hand_inventory, pipeline_orders, last_demand, quoted_lead_time):
    demand_ratio = 0.7434958549231803  # OPT_PARAM: {"initial": 0.7434958549231803, "min": 0.5, "max": 2.0, "type": "float"}
    safety_stock = 149.81829535247599  # OPT_PARAM: {"initial": 149.81829535247599, "min": 100.0, "max": 250.0, "type": "float"}
    demand_smoothing = 0.05  # OPT_PARAM: {"initial": 0.05, "min": 0.05, "max": 0.5, "type": "float"}

    smoothed_demand = demand_smoothing * last_demand + (1 - demand_smoothing) * 100.0
    target = demand_ratio * smoothed_demand + safety_stock
    order_amount = max(0.0, target - on_hand_inventory - np.sum(pipeline_orders))
    return order_amount
